surfaces.css:
/* 影の段を 3 つに分け、状態は前景色の薄い層で表す */
:where(header, nav, footer) {
  box-shadow: 0 1px 2px color-mix(in oklab, var(--foreground) 6%, transparent);
}
:where(.bg-card, article, aside) {
  border-radius: 1rem;
  box-shadow:
    0 1px 2px color-mix(in oklab, var(--foreground) 7%, transparent),
    0 4px 12px color-mix(in oklab, var(--foreground) 6%, transparent);
}
:where(button) {
  border-radius: 0.875rem;
  box-shadow:
    0 1px 2px color-mix(in oklab, var(--foreground) 8%, transparent),
    0 2px 6px color-mix(in oklab, var(--foreground) 7%, transparent);
}
:where(.bg-primary) {
  border-radius: 0.875rem;
  box-shadow:
    0 1px 2px color-mix(in oklab, var(--primary) 28%, transparent),
    0 6px 16px color-mix(in oklab, var(--primary) 24%, transparent);
}
:where(a, button, .bg-card):hover {
  background-image: linear-gradient(
    color-mix(in oklab, var(--foreground) 5%, transparent),
    color-mix(in oklab, var(--foreground) 5%, transparent)
  );
}
:where(a, button, .bg-card):active {
  background-image: linear-gradient(
    color-mix(in oklab, var(--foreground) 9%, transparent),
    color-mix(in oklab, var(--foreground) 9%, transparent)
  );
}

/* 半透明の面・背景のぼかし・縁の光で作り、ぼかせないブラウザでは不透明に近づける */
body {
  background-color: var(--background);
  background-image:
    radial-gradient(70rem 42rem at 8% -12%, color-mix(in oklab, var(--primary) 32%, transparent), transparent 70%),
    radial-gradient(54rem 38rem at 92% 8%, color-mix(in oklab, var(--brand-accent) 28%, transparent), transparent 72%),
    radial-gradient(46rem 34rem at 50% 108%, color-mix(in oklab, var(--accent) 70%, transparent), transparent 75%);
}
:where(header, body > nav) {
  background-color: color-mix(in oklab, var(--card) 62%, transparent);
  backdrop-filter: blur(18px) saturate(150%);
  border-bottom: 1px solid color-mix(in oklab, var(--foreground) 18%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--foreground) 22%, transparent);
}
:where(body > section:first-of-type, main > section:first-of-type, article > section:first-of-type) {
  background-color: color-mix(in oklab, var(--card) 55%, transparent);
  backdrop-filter: blur(22px) saturate(150%);
  border: 1px solid color-mix(in oklab, var(--foreground) 16%, transparent);
  border-radius: 1.25rem;
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--foreground) 24%, transparent);
}
:where(.bg-card, aside, article:not(:has(section))) {
  background-color: color-mix(in oklab, var(--card) 66%, transparent);
  backdrop-filter: blur(12px) saturate(140%);
  border: 1px solid color-mix(in oklab, var(--foreground) 14%, transparent);
  border-radius: 1rem;
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--foreground) 20%, transparent);
}
@supports not (backdrop-filter: blur(1px)) {
  :where(header, body > nav, body > section:first-of-type, main > section:first-of-type, article > section:first-of-type, .bg-card, aside, article:not(:has(section))) {
    background-color: color-mix(in oklab, var(--card) 94%, var(--background));
  }
}

/* べた塗りと線だけで面を作り、半透明・グラデーション・影を使わない */
:where(header, body > nav, footer) {
  background-color: var(--card);
  background-image: none;
  border-bottom: 2px solid var(--border);
  box-shadow: none;
}
:where(.bg-card, article, aside) {
  background-color: var(--card);
  background-image: none;
  border: 2px solid var(--border);
  border-radius: 0.25rem;
  box-shadow: none;
}
:where(button) {
  border: 2px solid var(--border);
  border-radius: 0.25rem;
  box-shadow: none;
}
:where(.bg-primary) {
  background-color: var(--primary);
  background-image: none;
  color: var(--primary-foreground);
  border: 2px solid var(--primary);
  border-radius: 0.25rem;
  box-shadow: none;
}
:where(body > section + section, main > section + section) {
  border-top: 2px solid var(--border);
}
:where([class*="bg-linear"], [class*="bg-radial"], [class*="bg-conic"]) {
  background-color: var(--primary);
  background-image: none;
  box-shadow: none;
}
:where(a, button):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
